SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.admittime, a.dischtime, a.deathtime, a.los, COUNT(DISTINCT e.medication) AS num_medications, SUM(CASE WHEN a.deathtime IS NOT NULL THEN 1 ELSE 0 END) AS deaths, SUM(CASE WHEN a.dischtime - a.admittime <= 30 THEN 1 ELSE 0 END) AS readmissions FROM patients p JOIN admissions a ON p.subject_id = a.subject_id LEFT JOIN emar e ON a.subject_id = e.subject_id AND a.hadm_id = e.hadm_id WHERE p.gender = 'M' AND p.anchor_age BETWEEN 41 AND 51 AND a.admittime BETWEEN 0 AND 48 AND (a.deathtime IS NOT NULL OR (a.dischtime - a.admittime) <= 30) GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.admittime, a.dischtime, a.deathtime, a.los ORDER BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.admittime, a.dischtime, a.deathtime, a.los NULLS LAST;